CREATE OR REPLACE FUNCTION trip_private.require_checkin_presentation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.phase='checkin' AND NEW.status IN ('released','declined') AND OLD.status='pending' AND NEW.presented_at IS NULL THEN RAISE EXCEPTION 'Present this Early Check-In task at a game night first'; END IF; RETURN NEW; END $$; REVOKE ALL ON FUNCTION trip_private.require_checkin_presentation() FROM PUBLIC,anon,authenticated; CREATE TRIGGER checkin_presentation_before_decision BEFORE UPDATE OF status ON public.mission_claims FOR EACH ROW EXECUTE FUNCTION trip_private.require_checkin_presentation();